import React from 'react'
import './BambooGrove.css'

// Realistic bamboo groves framing the counter section and bursting up into
// the hero. The drawings are static SVGs in public/bamboo, generated by
// scripts/generate-bamboo.py; loading them as images keeps them cached and
// out of the page's JavaScript.
const SIDES = ['left', 'right']

const BambooGrove = () => (
  <div className='bamboo-groves' aria-hidden='true'>
    {SIDES.map((side) => (
      <img
        key={side}
        className={`bamboo-grove bamboo-grove-${side}`}
        src={`/bamboo/grove-${side}.svg`}
        alt=''
        draggable='false'
        decoding='async'
      />
    ))}
  </div>
)

export default BambooGrove
